    43  int
    44  ares_parse_soa_reply(const unsigned char *abuf, int alen,
    45                       struct ares_soa_reply **soa_out)
    46  {
    47    const unsigned char *aptr;
    48    long len;
    49    char *qname = NULL, *rr_name = NULL;
    50    struct ares_soa_reply *soa = NULL;
    51    int qdcount, ancount, qclass;
    52    int status, i, rr_type, rr_class, rr_len;
    53
    54    if (alen < HFIXEDSZ)
    55      return ARES_EBADRESP;
    56
    57    /* parse message header */
    58    qdcount = DNS_HEADER_QDCOUNT(abuf);
    59    ancount = DNS_HEADER_ANCOUNT(abuf);
    60
    61    if (qdcount != 1)
    62      return ARES_EBADRESP;
    63    if (ancount == 0)
    64      return ARES_EBADRESP;
    65
    66    aptr = abuf + HFIXEDSZ;
    67
    68    /* query name */
    69    status = ares__expand_name_for_response(aptr, abuf, alen, &qname, &len);
    70    if (status != ARES_SUCCESS)
    71      goto failed_stat;
    72    aptr += len;
    73
    74    qclass = DNS_QUESTION_TYPE(aptr);
    75
    76    /* skip qtype & qclass */
    77    if (aptr + QFIXEDSZ > abuf + alen)
    78      goto failed;
    79    aptr += QFIXEDSZ;
    80
    81    /* qclass of SOA with multiple answers */
    82    if (qclass == T_SOA && ancount > 1)
    83      goto failed;
    84
    85    /* examine all the records, break and return if found soa */
    86    for (i = 0; i < ancount; i++)
    87    {
    88      status = ares__expand_name_for_response (aptr, abuf, alen, &rr_name, &len);
    89      if (status != ARES_SUCCESS)
    90       {
    91        ares_free(rr_name);
    92        goto failed_stat;
    93       }
    94
    95      aptr += len;
    96      if ( aptr + RRFIXEDSZ > abuf + alen )
    97      {
    98        ares_free(rr_name);
    99        status = ARES_EBADRESP;
   100        goto failed_stat;
   101      }
   102      rr_type = DNS_RR_TYPE( aptr );
   103      rr_class = DNS_RR_CLASS( aptr );
   104      rr_len = DNS_RR_LEN( aptr );
   105      aptr += RRFIXEDSZ;
   106      if (aptr + rr_len > abuf + alen)
   107        {
   108          ares_free(rr_name);
   109          status = ARES_EBADRESP;
   110          goto failed_stat;
   111        }
   112      if ( rr_class == C_IN && rr_type == T_SOA )
   113      {
   114        /* allocate result struct */
   115        soa = ares_malloc_data(ARES_DATATYPE_SOA_REPLY);
   116        if (!soa)
   117          {
   118            ares_free(rr_name);
   119            status = ARES_ENOMEM;
   120            goto failed_stat;
   121          }
   122
   123        /* nsname */
   124        status = ares__expand_name_for_response(aptr, abuf, alen, &soa->nsname,
   125                                                 &len);
   126        if (status != ARES_SUCCESS)
   127         {
   128          ares_free(rr_name);
   129          goto failed_stat;
   130         }
   131        aptr += len;
   132
   133        /* hostmaster */
   134        status = ares__expand_name_for_response(aptr, abuf, alen,
   135                                                 &soa->hostmaster, &len);
   136        if (status != ARES_SUCCESS)
   137         {
   138          ares_free(rr_name);
   139          goto failed_stat;
   140         }
   141        aptr += len;
   142
   143        /* integer fields */
   144        if (aptr + 5 * 4 > abuf + alen)
   145         {
   146          ares_free(rr_name);
   147          goto failed;
   148         }
   149        soa->serial = DNS__32BIT(aptr + 0 * 4);
   150        soa->refresh = DNS__32BIT(aptr + 1 * 4);
   151        soa->retry = DNS__32BIT(aptr + 2 * 4);
   152        soa->expire = DNS__32BIT(aptr + 3 * 4);
   153        soa->minttl = DNS__32BIT(aptr + 4 * 4);
   154
   155        ares_free(qname);
   156        ares_free(rr_name);
   157
   158        *soa_out = soa;
   159
   160        return ARES_SUCCESS;
   161      }
   162      aptr += rr_len;
   163
   164      ares_free(rr_name);
   165
   166      if (aptr > abuf + alen)
   167        goto failed_stat;
   168    }
   169    /* no SOA record found */
   170    status = ARES_EBADRESP;
   171    goto failed_stat;
   172  failed:
   173    status = ARES_EBADRESP;
   174
   175  failed_stat:
   176    if (soa)
   177      ares_free_data(soa);
   178    if (qname)
   179      ares_free(qname);
   180    return status;
   181  }
